import React, { useEffect, useMemo, useState } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  TextField,
  Button,
  Grid,
  Alert,
  CircularProgress,
  Chip,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Divider,
  List,
  ListItem,
  ListItemText,
  LinearProgress,
  Tooltip,
} from '@mui/material';
import {
  ExpandMore,
  Psychology,
  Download,
  Visibility,
} from '@mui/icons-material';
import { useSearchParams } from 'react-router-dom';

interface JiraSettings {
  url: string;
  email: string;
  apiToken: string;
  projectKey: string;
  daysBack?: number;
  jql?: string;
}

interface AnalysisResult {
  rootCauseCategory: string;
  shortSummary: string;
  keyIndicators: string[];
  suggestedNextSteps: string[];
  confidence: number;
  scoreBreakdown: Record<string, number>;
  extractedDetails: {
    summary: string;
    status: string;
    priority: string;
    description: string;
    resolutionNotes: string;
    comments: string[];
    labels: string[];
    components: string[];
    logHints: string[];
  };
}

const RootCauseAnalyzer: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [ticketKey, setTicketKey] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<AnalysisResult | null>(null);

  const jiraConfigured = useMemo(() => {
    try {
      const raw = localStorage.getItem('jiraSettings');
      if (!raw) return false;
      const settings = JSON.parse(raw) as JiraSettings;
      return Boolean(settings.url && settings.email && settings.apiToken);
    } catch {
      return false;
    }
  }, []);

  const getJiraSettings = (): JiraSettings | null => {
    try {
      const raw = localStorage.getItem('jiraSettings');
      if (!raw) return null;
      return JSON.parse(raw) as JiraSettings;
    } catch {
      return null;
    }
  };

  const analyzeTicket = async (inputTicketKey: string) => {
    const normalizedTicketKey = inputTicketKey.trim().toUpperCase();
    if (!normalizedTicketKey) {
      setError('Please enter a JIRA ticket ID (for example: NCIP-1234).');
      return;
    }

    const jiraSettings = getJiraSettings();
    if (!jiraSettings?.url || !jiraSettings?.email || !jiraSettings?.apiToken) {
      setError('Jira is not configured. Go to Settings and save your Jira credentials first.');
      return;
    }

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const response = await fetch('http://localhost:8000/api/root-cause-analyze', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ticketKey: normalizedTicketKey,
          jiraSettings,
        }),
      });

      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.detail || `Analysis failed (${response.status})`);
      }

      setResult(data.analysis as AnalysisResult);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to analyze ticket');
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyze = async () => {
    await analyzeTicket(ticketKey);
  };

  useEffect(() => {
    const queryTicket = (searchParams.get('ticket') || '').trim().toUpperCase();
    if (!queryTicket) return;
    setTicketKey(queryTicket);
    analyzeTicket(queryTicket);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams]);

  const exportAnalysis = () => {
    if (!result) return;
    const payload = {
      ticketKey: ticketKey.trim().toUpperCase(),
      generatedAt: new Date().toISOString(),
      analysis: result,
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `${payload.ticketKey || 'ticket'}-root-cause-analysis.json`;
    anchor.click();
    URL.revokeObjectURL(url);
  };

  return (
    <Box>
      <Typography variant="h4" component="h1" gutterBottom>
        🧠 Root Cause Analyzer
      </Typography>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
        Enter a JIRA ticket ID to fetch issue details and run explainable root cause classification.
      </Typography>

      {!jiraConfigured && (
        <Alert severity="warning" sx={{ mb: 2 }}>
          Jira credentials are not configured. Save them in Settings before analyzing tickets.
        </Alert>
      )}

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Grid container spacing={2} alignItems="center">
            <Grid item xs={12} md={8}>
              <TextField
                fullWidth
                label="JIRA Ticket ID"
                placeholder="NCIP-1234"
                value={ticketKey}
                onChange={(e) => setTicketKey(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleAnalyze();
                  }
                }}
              />
            </Grid>
            <Grid item xs={12} md={4}>
              <Button
                fullWidth
                variant="contained"
                startIcon={loading ? <CircularProgress size={18} /> : <Psychology />}
                onClick={handleAnalyze}
                disabled={loading}
              >
                {loading ? 'Analyzing...' : 'Analyze'}
              </Button>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {result && (
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Box display="flex" justifyContent="space-between" alignItems="center" flexWrap="wrap" gap={1}>
                  <Typography variant="h6">Analysis Result</Typography>
                  <Button variant="outlined" startIcon={<Download />} onClick={exportAnalysis}>
                    Export
                  </Button>
                </Box>

                <Box mt={2} display="flex" gap={1} flexWrap="wrap" alignItems="center">
                  <Typography variant="subtitle2">Root Cause Category:</Typography>
                  <Chip color="primary" label={result.rootCauseCategory} />
                </Box>

                <Box mt={2}>
                  <Typography variant="subtitle2" gutterBottom>
                    Confidence
                  </Typography>
                  <Tooltip title={`${Math.round(result.confidence * 100)}%`}>
                    <Box>
                      <LinearProgress variant="determinate" value={Math.round(result.confidence * 100)} sx={{ height: 10, borderRadius: 5 }} />
                    </Box>
                  </Tooltip>
                </Box>

                <Box mt={2}>
                  <Typography variant="subtitle2">Short Summary</Typography>
                  <Typography variant="body2" color="text.secondary">
                    {result.shortSummary}
                  </Typography>
                </Box>

                <Divider sx={{ my: 2 }} />

                <Typography variant="subtitle2" gutterBottom>
                  Key Indicators
                </Typography>
                <List dense>
                  {result.keyIndicators.map((indicator, idx) => (
                    <ListItem key={`${indicator}-${idx}`} disableGutters>
                      <ListItemText primary={`• ${indicator}`} />
                    </ListItem>
                  ))}
                </List>

                <Typography variant="subtitle2" gutterBottom>
                  Suggested Next Steps
                </Typography>
                <List dense>
                  {result.suggestedNextSteps.map((step, idx) => (
                    <ListItem key={`${step}-${idx}`} disableGutters>
                      <ListItemText primary={`${idx + 1}. ${step}`} />
                    </ListItem>
                  ))}
                </List>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12}>
            <Accordion>
              <AccordionSummary expandIcon={<ExpandMore />}>
                <Box display="flex" alignItems="center" gap={1}>
                  <Visibility fontSize="small" />
                  <Typography>View Extracted Ticket Details</Typography>
                </Box>
              </AccordionSummary>
              <AccordionDetails>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <Typography variant="subtitle2">Summary</Typography>
                    <Typography variant="body2" color="text.secondary">{result.extractedDetails.summary || '—'}</Typography>
                  </Grid>
                  <Grid item xs={12} md={3}>
                    <Typography variant="subtitle2">Status</Typography>
                    <Typography variant="body2" color="text.secondary">{result.extractedDetails.status || '—'}</Typography>
                  </Grid>
                  <Grid item xs={12} md={3}>
                    <Typography variant="subtitle2">Priority</Typography>
                    <Typography variant="body2" color="text.secondary">{result.extractedDetails.priority || '—'}</Typography>
                  </Grid>

                  <Grid item xs={12}>
                    <Typography variant="subtitle2">Description</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ whiteSpace: 'pre-wrap' }}>
                      {result.extractedDetails.description || '—'}
                    </Typography>
                  </Grid>

                  <Grid item xs={12}>
                    <Typography variant="subtitle2">Resolution Notes</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ whiteSpace: 'pre-wrap' }}>
                      {result.extractedDetails.resolutionNotes || '—'}
                    </Typography>
                  </Grid>

                  <Grid item xs={12}>
                    <Typography variant="subtitle2">Comments ({result.extractedDetails.comments.length})</Typography>
                    <List dense>
                      {result.extractedDetails.comments.length === 0 ? (
                        <ListItem disableGutters>
                          <ListItemText primary="No comments available." />
                        </ListItem>
                      ) : (
                        result.extractedDetails.comments.map((comment, idx) => (
                          <ListItem key={`comment-${idx}`} disableGutters>
                            <ListItemText primary={`• ${comment}`} />
                          </ListItem>
                        ))
                      )}
                    </List>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <Typography variant="subtitle2">Labels</Typography>
                    <Box display="flex" gap={1} flexWrap="wrap" mt={1}>
                      {result.extractedDetails.labels.length === 0 ? (
                        <Typography variant="body2" color="text.secondary">—</Typography>
                      ) : (
                        result.extractedDetails.labels.map((label) => (
                          <Chip key={label} label={label} size="small" variant="outlined" />
                        ))
                      )}
                    </Box>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <Typography variant="subtitle2">Components</Typography>
                    <Box display="flex" gap={1} flexWrap="wrap" mt={1}>
                      {result.extractedDetails.components.length === 0 ? (
                        <Typography variant="body2" color="text.secondary">—</Typography>
                      ) : (
                        result.extractedDetails.components.map((component) => (
                          <Chip key={component} label={component} size="small" variant="outlined" />
                        ))
                      )}
                    </Box>
                  </Grid>

                  <Grid item xs={12}>
                    <Typography variant="subtitle2">Log/Failure Hints</Typography>
                    <List dense>
                      {result.extractedDetails.logHints.length === 0 ? (
                        <ListItem disableGutters>
                          <ListItemText primary="No explicit log/error lines detected in ticket content." />
                        </ListItem>
                      ) : (
                        result.extractedDetails.logHints.map((hint, idx) => (
                          <ListItem key={`log-${idx}`} disableGutters>
                            <ListItemText primary={`• ${hint}`} />
                          </ListItem>
                        ))
                      )}
                    </List>
                  </Grid>
                </Grid>
              </AccordionDetails>
            </Accordion>
          </Grid>
        </Grid>
      )}
    </Box>
  );
};

export default RootCauseAnalyzer;
